"use strict";(self.webpackChunkevmcrispr_doc=self.webpackChunkevmcrispr_doc||[]).push([[2623],{2838:function(e){e.exports=JSON.parse('{"pluginId":"getStarted","version":"current","label":"Next","banner":null,"badge":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","label":"What is EVMcrispr?","href":"/evmcrispr-doc/getStarted/","docId":"getStarted"},{"type":"link","label":"Modularity","href":"/evmcrispr-doc/getStarted/modularity","docId":"modularity"},{"type":"link","label":"Simulating Scripts","href":"/evmcrispr-doc/getStarted/simulations","docId":"simulations"},{"type":"link","label":"Syntactic Sugar","href":"/evmcrispr-doc/getStarted/syntaxSugar","docId":"syntaxSugar"}]},"docs":{"getStarted":{"id":"getStarted","title":"What is EVMcrispr?","description":"EVMcrispr is a powerful tool that combines a command line interface with a Javascript library to create multi-action EVM scripts, including interacting with Aragon DAOs. With it, you can bundle many operations into just one script, generating a singular transaction, or create multiple transactions using a single script.","sidebar":"defaultSidebar"},"modularity":{"id":"modularity","title":"Modularity","description":"EVMcrispr has been designed as a tool that can support various platforms and protocols. Specialized commands and helpers have been broken down into modules that users can load separately. This allows EVMcrispr to scale and become modular.","sidebar":"defaultSidebar"},"simulations":{"id":"simulations","title":"Simulating Scripts","description":"With the power of Tenderly you can simulate your EVM scripts right inside the terminal. You\'ll need a Tenderly subscription and an Access Token to get started. You can find how to get an Access Token in the Tenderly documentation.","sidebar":"defaultSidebar"},"syntaxSugar":{"id":"syntaxSugar","title":"Syntactic Sugar","description":"One of the real gems of EVMcrispr is the shorthand notations you can leverage to make code easier to understand and write. We\'ll cover most of the primary syntax sugar you leverage while writing scripts with EVMcrispr.","sidebar":"defaultSidebar"}}}')}}]);